import React from 'react';

export default function Sidebar({ currentSubPage, setCurrentSubPage, onLogoutClick }) {
  const menuItems = [
    { name: 'Overview', icon: '👁️‍🗨️' },
    { name: 'Students', icon: '👨‍🎓' },
    { name: 'Teachers & Classes', icon: '🏫' },
    { name: 'Reports', icon: '📋' },
    { name: 'Settings', icon: '⚙️' },
  ];

  return (
    <div style={{ 
      width: '260px', 
      backgroundColor: '#1e40af', 
      color: '#ffffff', 
      padding: '25px 15px', 
      display: 'flex', 
      flexDirection: 'column', 
      justifyContent: 'space-between',
      alignSelf: 'stretch',
    }}>
      
      <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
        <div style={{ padding: '0 15px 20px 15px', borderBottom: '1px solid rgba(255,255,255,0.1)', marginBottom: '15px' }}>
          <span style={{ fontSize: '18px', fontWeight: 'bold', letterSpacing: '0.5px' }}>📌 Admin Panel</span>
        </div>

        {menuItems.map((item, i) => {
          const isActive = currentSubPage === item.name;
          return (
            <div 
              key={i} 
              onClick={() => setCurrentSubPage(item.name)}
              style={{ 
                padding: '12px 18px', 
                borderRadius: '8px', 
                cursor: 'pointer', 
                display: 'flex', 
                alignItems: 'center', 
                gap: '12px', 
                backgroundColor: isActive ? '#1d4ed8' : 'transparent', 
                fontWeight: isActive ? '600' : '400' 
              }}
            >
              <span style={{ fontSize: '16px' }}>{item.icon}</span> 
              <span style={{ fontSize: '14px' }}>{item.name}</span>
            </div>
          );
        })}
      </div>

      <div 
        onClick={onLogoutClick}
        style={{ 
          padding: '12px 18px', 
          borderRadius: '8px', 
          cursor: 'pointer', 
          display: 'flex', 
          alignItems: 'center', 
          gap: '12px', 
          backgroundColor: '#dc2626', 
          fontWeight: '600',
          marginTop: 'auto'
        }}
      >
        <span style={{ fontSize: '16px' }}>🚪</span> 
        <span style={{ fontSize: '14px' }}>Logout</span>
      </div>

    </div>
  );
}
